package ru.mosvegas.casino.client.state;

import net.minecraft.util.math.MathHelper;

/**
 * Timings (seconds) of the dealer's hand animations generated by {@code tools/AssetGen.java}. The client starts
 * an animation on the dealer and moves the card or chips along with the tracked palm, so both stay in sync.
 * If you replace the animations in Blockbench, keep these moments (or change them here).
 */
public final class Choreo {
    private Choreo() {}

    public enum DealMode { LEFT_HAND, HANDOFF, SELF }

    /** The card leaves the shoe in the left hand. */
    public static final float GRAB = 0.10f;
    /** Left hand gives the card to the right hand in front of the chest. */
    public static final float HANDOFF = 0.22f;
    public static final float RELEASE_LEFT = 0.36f;
    public static final float RELEASE_RIGHT = 0.40f;
    public static final float RELEASE_SELF = 0.34f;
    /** After the release the card slides over the felt to its place. */
    public static final float SLIDE = 0.15f;
    /** Minimum spacing between two dealt cards (the deal animation is 0.56 s long). */
    public static final float DEAL_GAP = 0.45f;

    public static float release(DealMode mode) {
        return switch (mode) {
            case LEFT_HAND -> RELEASE_LEFT;
            case HANDOFF -> RELEASE_RIGHT;
            case SELF -> RELEASE_SELF;
        };
    }

    // reach_<k>: hand at the tray, at the bet, back at the tray
    public static final float REACH_AT_TRAY = 0.06f;
    public static final float REACH_PICK = 0.18f;
    public static final float REACH_AT_BET = 0.28f;
    public static final float REACH_BACK = 0.52f;
    public static final float REACH_DROP = 0.12f;
    /** One box after another while paying (seconds per box). */
    public static final float PAY_SLOT = 0.65f;
    public static final float PAY_LEAD = 0.3f;

    // collect: hands sweep from the sides to the middle, meet, right hand drops the pile in the discard holder
    public static final float SWEEP_FROM = 0.25f;
    public static final float SWEEP_SPAN = 0.60f;
    public static final float PULL = 0.22f;
    public static final float MERGE_FROM = 1.10f;
    public static final float MERGE_TO = 1.25f;
    public static final float DROP_FROM = 1.70f;
    public static final float DROP_TO = 1.82f;
    public static final float COLLECT_END = 2.2f;

    /** When the sweeping hand reaches a card lying at the given angle around the felt centre. */
    public static float pickTime(double angleDeg) {
        boolean left = angleDeg >= 90;
        double f = left ? (160 - angleDeg) / 66 : (angleDeg - 20) / 66;
        return SWEEP_FROM + SWEEP_SPAN * (float) MathHelper.clamp(f, 0, 1);
    }

    public static float ease(float t) {
        t = MathHelper.clamp(t, 0f, 1f);
        return t * t * (3 - 2 * t);
    }

    public static float easeOut(float t) {
        t = MathHelper.clamp(t, 0f, 1f);
        return 1 - (1 - t) * (1 - t) * (1 - t);
    }
}
